import{_ as t,c as s,o as n,a3 as a}from"./chunks/framework.BNw1pucY.js";const m=JSON.parse('{"title":"Project layout","description":"The canonical bot/ folder layout and its path-derived naming rules.","frontmatter":{"title":"Project layout","description":"The canonical bot/ folder layout and its path-derived naming rules."},"headers":[],"relativePath":"reference/project-layout.md","filePath":"reference/project-layout.md"}'),o={name:"reference/project-layout.md"};function d(c,e,r,i,l,p){return n(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="project-layout" tabindex="-1">Project layout <a class="header-anchor" href="#project-layout" aria-label="Permalink to &quot;Project layout&quot;">​</a></h1><p>An Agent SDK project keeps agent files under <code>bot/</code>, and each file&#39;s path determines how Agent SDK loads it. <a href="./../evals.html">Evals</a> live in <code>evals/</code> at the project root, beside <code>bot/</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-agent/</span></span>
<span class="line"><span>├── package.json</span></span>
<span class="line"><span>├── bot/</span></span>
<span class="line"><span>│   ├── agent.ts</span></span>
<span class="line"><span>│   ├── instructions.md</span></span>
<span class="line"><span>│   ├── tools/</span></span>
<span class="line"><span>│   │   └── approve_pr.ts</span></span>
<span class="line"><span>│   ├── skills/</span></span>
<span class="line"><span>│   │   └── pr-review.md</span></span>
<span class="line"><span>│   ├── mcp-connections/</span></span>
<span class="line"><span>│   │   └── linear.ts</span></span>
<span class="line"><span>│   ├── subagents/</span></span>
<span class="line"><span>│   │   └── reviewer/</span></span>
<span class="line"><span>│   │       ├── agent.ts</span></span>
<span class="line"><span>│   │       └── instructions.md</span></span>
<span class="line"><span>│   ├── extensions/</span></span>
<span class="line"><span>│   │   └── ci.ts</span></span>
<span class="line"><span>│   ├── channels/</span></span>
<span class="line"><span>│   │   └── github.ts</span></span>
<span class="line"><span>│   └── hooks/</span></span>
<span class="line"><span>│       └── audit.ts</span></span>
<span class="line"><span>└── evals/</span></span>
<span class="line"><span>    ├── evals.config.ts</span></span>
<span class="line"><span>    └── readiness.eval.ts</span></span></code></pre></div><p>The root agent&#39;s name is the <code>name</code> in <code>package.json</code>, or else the directory name. When one server hosts multiple agents, each slug is the agent&#39;s directory name, and it must match <code>[A-Za-z0-9][A-Za-z0-9_-]*</code> and can&#39;t be <code>v1</code>, <code>playground</code>, or <code>docs</code>.</p><h2 id="folder-reference" tabindex="-1">Folder reference <a class="header-anchor" href="#folder-reference" aria-label="Permalink to &quot;Folder reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path under <code>bot/</code></th><th>What it is</th><th>Reference</th></tr></thead><tbody><tr><td><code>agent.ts</code></td><td><code>defineAgent({ model?, local? })</code></td><td><a href="./agent-config.html">Agent config</a></td></tr><tr><td><code>instructions.md</code></td><td>Always-on system prompt, required on the root agent</td><td><a href="./instructions.html">Instructions</a></td></tr><tr><td><code>tools/&lt;name&gt;.ts</code></td><td>One typed tool named after the file</td><td><a href="./tools.html">Tools</a></td></tr><tr><td><code>skills/*</code></td><td>Procedures loaded on demand</td><td><a href="./skills.html">Skills</a></td></tr><tr><td><code>mcp-connections/&lt;name&gt;.ts</code></td><td>MCP servers for the model, server tools, and handlers</td><td><a href="./connections.html">MCP connections</a></td></tr><tr><td><code>host-connections/&lt;name&gt;.ts</code></td><td>MCP servers for host code and <code>mcp oauth</code>. The model never sees them</td><td><a href="./connections.html">MCP connections</a></td></tr><tr><td><code>subagents/&lt;id&gt;/</code></td><td>Child agent directory with a required <code>description</code></td><td><a href="./subagents.html">Subagents</a></td></tr><tr><td><code>extensions/&lt;ns&gt;.ts</code> or <code>extensions/&lt;ns&gt;/</code></td><td>Extension or Cursor plugin mount. Its contributions become <code>&lt;ns&gt;__&lt;name&gt;</code></td><td><a href="./extensions.html">Extensions</a></td></tr><tr><td><code>channels/&lt;name&gt;.ts</code></td><td>HTTP routes under <code>/v1/channels/&lt;name&gt;</code></td><td><a href="./channels.html">Channels</a></td></tr><tr><td><code>hooks/*.ts</code></td><td>Observe-only event subscribers</td><td><a href="./hooks.html">Hooks</a></td></tr><tr><td><code>artifacts.ts</code></td><td>Artifact kinds, the <code>tag_artifact</code> opt-in, and retention</td><td><a href="./artifacts.html">Artifacts</a></td></tr><tr><td><code>schedules/*</code></td><td>Cron-driven runs</td><td><a href="./schedules.html">Schedules</a></td></tr><tr><td><code>reminders/*.ts</code></td><td>Named reminder handlers</td><td><a href="./schedules.html#reminders">Reminders</a></td></tr><tr><td><code>sandbox/workspace/**</code></td><td>Seed files copied into each local session workspace</td><td><a href="./sessions.html#local-session-workspace">Sessions</a></td></tr><tr><td><code>lib/</code></td><td>Shared imports, never discovered</td><td>None</td></tr></tbody></table><p>Every eval project needs <code>evals/evals.config.ts</code>. Each <code>evals/**/*.eval.ts</code> file is a suite whose case IDs come from its path.</p><p>A <code>.ts</code> file in a discovery folder loads as a definition, and an unrecognized directory produces a validation warning. Agent SDK still loads existing projects rooted at <code>agent/</code>.</p><h2 id="inspect-discovery" tabindex="-1">Inspect discovery <a class="header-anchor" href="#inspect-discovery" aria-label="Permalink to &quot;Inspect discovery&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk validate --dir .    # diagnostics, non-zero exit on errors</span></span>
<span class="line"><span>agent-sdk info --dir .        # discovered surface</span></span>
<span class="line"><span>agent-sdk info --dir . --json # same shape as GET /v1/info</span></span></code></pre></div><p><code>serve</code> refuses to start on errors. Warnings do not block startup. When <code>info</code> omits a tool or channel, the file is in the wrong directory or has the wrong extension.</p>`,11)])])}const u=t(o,[["render",d]]);export{m as __pageData,u as default};
